"use strict";

/**
 * CODEX 3.0 bundler.
 *
 * Obsidian 只接受自包含的插件 main.js。这里做一个极小的 CommonJS 打包器：
 * - 本目录内的相对 require 会被内联进 __modules；
 * - require("obsidian") 等外部模块保留给 Obsidian 运行时；
 * - 输出仍然是标准 CommonJS，module.exports 指向插件入口。
 */

const fs = require("node:fs");
const path = require("node:path");

function resolveModule(fromFile, spec) {
  if (!spec.startsWith(".")) return null;
  const base = path.resolve(path.dirname(fromFile), spec);
  const candidates = [base, `${base}.js`, path.join(base, "index.js")];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return path.resolve(candidate);
  }
  throw new Error(`无法解析模块 ${spec}（来自 ${fromFile}）`);
}

function bundle(entryFile) {
  const modules = [];
  const idByFile = new Map();

  function addModule(file) {
    const absolute = path.resolve(file);
    if (idByFile.has(absolute)) return idByFile.get(absolute);
    const id = modules.length;
    idByFile.set(absolute, id);
    modules.push({ id, file: absolute, code: "" });

    const raw = fs.readFileSync(absolute, "utf8");
    const source = absolute.endsWith('.ts') ? require('node:module').stripTypeScriptTypes(raw) : raw;
    const code = source.replace(/require\(\s*(["'])([^"']+)\1\s*\)/g, (match, quote, spec) => {
      if (!spec.startsWith(".")) return match;
      const resolved = resolveModule(absolute, spec);
      const dependencyId = addModule(resolved);
      return `__require(${dependencyId})`;
    });
    modules[id].code = code;
    return id;
  }

  const entryId = addModule(entryFile);
  const parts = [
    '"use strict";',
    "/* Generated by CODEX plugin bundler. Edit source modules, not this file. */",
    "const __modules = [",
  ];
  for (const module of modules) {
    parts.push(`function (module, exports, __require) {\n${module.code}\n},`);
  }
  parts.push("];");
  parts.push("const __cache = {};");
  parts.push("function __require(id) {");
  parts.push("  if (Object.prototype.hasOwnProperty.call(__cache, id)) return __cache[id].exports;");
  parts.push("  const module = { exports: {} };");
  parts.push("  __cache[id] = module;");
  parts.push("  __modules[id](module, module.exports, __require);");
  parts.push("  return module.exports;");
  parts.push("}");
  parts.push(`module.exports = __require(${entryId});`);
  parts.push("");
  return { code: parts.join("\n"), modules };
}

module.exports = { bundle, resolveModule };
